// SIRAJ Brand Guidelines v1.0 — generates 20-Brand-Guidelines/source/siraj-brand-guidelines.html,
// then renders PDF (1920×1080 pages) + PNG page previews + contact sheet.
// Assets are discovered at build time, so the document always reflects the repository.
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const R = require('./lib/render');
const L = require('./lib/logo');

const ROOT = R.ROOT;
const OUT = path.join(ROOT, '20-Brand-Guidelines');
const SRC = path.join(OUT, 'source');
const ASSETS = path.join(OUT, 'assets');
fs.mkdirSync(SRC, { recursive: true }); fs.mkdirSync(ASSETS, { recursive: true });
const rel = (p) => path.relative(SRC, path.join(ROOT, p)).split(path.sep).join('/');
const exists = (p) => fs.existsSync(path.join(ROOT, p));
const glob = (dir, re) => { const d = path.join(ROOT, dir); if (!fs.existsSync(d)) return []; const out = []; (function walk(x) { for (const f of fs.readdirSync(x)) { const p = path.join(x, f); if (fs.statSync(p).isDirectory()) walk(p); else if (re.test(f)) out.push(path.relative(ROOT, p).split(path.sep).join('/')); } })(d); return out.sort(); };
const first = (dir, re) => glob(dir, re)[0];
const BR = require('../00-Brand-Foundation/brand.config.json');
const PAL = require('../02-Colours/SIRAJ_Colour-Palette_v1.0.json').palette;
const TOK = require('../09-Design-System/tokens/build/siraj-tokens.json');

// ------------------------------------------------------------------------------------------- helpers
const img = (p, style = '', cls = '') => (p && exists(p) ? `<img class="${cls}" src="${rel(p)}" style="${style}" loading="eager">` : `<div class="missing" style="${style}">asset pending · ${p || ''}</div>`);
const bgImg = (p) => (p && exists(p) ? `background-image:url('${rel(p)}')` : 'background:#EFE7E0');
const logo = (variant = 'primary', h = 60, style = '') => L.inline({ variant, style: `height:${h}px;width:auto;display:block;${style}` });
const eb = (t) => `<div class="eb"><i></i>${t}</div>`;
let pageNo = 0;
const TOC = [];
let secNo = 0;
const stripNo = (t) => String(t).replace(/^\d+\s*·\s*/, '');
function page({ sec = '', title = '', body = '', dark = false, cls = '', toc = null, footer = true, raw = false }) {
  pageNo++;
  if (toc) { secNo++; TOC.push([`${String(secNo).padStart(2, '0')} · ${stripNo(toc)}`, pageNo]); }
  if (sec && sec !== 'Contents') sec = `${String(secNo).padStart(2, '0')} · ${stripNo(sec)}`;
  if (raw) return `<section class="page ${dark ? 'dark' : ''} ${cls}">${body}${footer ? foot(sec, dark) : ''}</section>`;
  return `<section class="page ${dark ? 'dark' : ''} ${cls}">
    <header class="ph"><div class="sec">${sec}</div><h2>${title}</h2></header>
    <div class="pb">${body}</div>${footer ? foot(sec, dark) : ''}</section>`;
}
const foot = (sec, dark) => `<footer class="pf"><span>${logo(dark ? 'sand' : 'primary', 16)}</span><span>Brand Guidelines v1.0 · ${sec.replace(/<[^>]+>/g, '')}</span><span class="pn">${String(pageNo).padStart(2, '0')}</span></footer>`;
const divider = (n, title, ar, still, toc) => page({ toc, dark: true, raw: true, footer: false, cls: 'divider', body: `<div class="dv-bg" style="${bgImg(still)}"></div><div class="dv-shade"></div><div class="dv"><div class="dv-n">${String(secNo + 1).padStart(2, '0')}</div><h1>${title}</h1><div class="dv-ar">${ar}</div></div>` });
const rule = '<div class="hr"></div>';
const doList = (items, ok = true) => `<ul class="dl ${ok ? 'ok' : 'no'}">${items.map((i) => `<li>${i}</li>`).join('')}</ul>`;
const swatch = (e, big = false) => `<div class="sw ${big ? 'big' : ''}"><div class="chip" style="background:${e.hex};${['#F7F2ED', '#FFFFFF', '#EFE7E0', '#D6C0B2'].includes(e.hex) ? 'box-shadow:inset 0 0 0 1px #E3D6CC' : ''}"></div><div class="sm"><b>${e.name}</b><span>${e.hex} · RGB ${e.rgb.join(' ')}</span><span>CMYK ${e.cmyk.join(' ')}</span><span>${e.pantone}</span></div></div>`;

// ---- frame strips from motion exports ------------------------------------------------------------
function strip(video, out, times, w = 480) {
  const v = path.join(ROOT, video); if (!fs.existsSync(v)) return null;
  const o = path.join(ASSETS, out);
  const tmp = times.map((t, i) => { const f = path.join(ASSETS, `.f${i}.png`); execFileSync('ffmpeg', ['-v', 'error', '-y', '-ss', String(t), '-i', v, '-frames:v', '1', '-vf', `scale=${w}:-1`, f]); return f; });
  execFileSync('convert', [...tmp, '+append', o]); tmp.forEach((f) => fs.rmSync(f));
  return path.relative(ROOT, o);
}

// ---- misuse examples (generated from the official geometry) -----------------------------------------
function misuse() {
  const P = L.P; const g = (fill = '#602733', lumen = '#AA9180', extra = '') => `<g ${extra}>${P.map((p) => `<path d="${p.d}" fill="${p.role === 'lumen' ? lumen : fill}"/>`).join('')}</g>`;
  const box = `viewBox="10 46 120 50"`;
  const ex = [
    ['Do not stretch or condense', `<svg ${box}>${g('#602733', '#AA9180', 'transform="translate(-30 0) scale(1.45 1)"')}</svg>`],
    ['Do not recolour', `<svg ${box}>${g('#2F6B8A', '#E0B040')}</svg>`],
    ['Do not rotate', `<svg ${box}>${g('#602733', '#AA9180', 'transform="rotate(-12 70 70)"')}</svg>`],
    ['No effects or shadows', `<svg ${box}><defs><filter id="ds"><feDropShadow dx="1.2" dy="1.6" stdDeviation="0.8" flood-opacity=".55"/></filter></defs>${g('#602733', '#AA9180', 'filter="url(#ds)"')}</svg>`],
    ['No outlines', `<svg ${box}>${g('none', 'none', 'stroke="#602733" stroke-width=".5"')}</svg>`],
    ['No gradients in the letters', `<svg ${box}><defs><linearGradient id="gg"><stop offset="0" stop-color="#C9A227"/><stop offset="1" stop-color="#602733"/></linearGradient></defs>${g('url(#gg)', 'url(#gg)')}</svg>`],
    ['Do not let silk cross the logo', `<svg ${box}>${g('#602733')}<path d="M10,80 C40,60 70,90 130,58 L130,66 C70,98 40,68 10,88Z" fill="#81404C" opacity=".95"/></svg>`],
    ['Do not place it in a container', `<svg ${box}><rect x="15" y="50" width="110" height="42" rx="21" fill="#602733"/>${g('#D6C0B2', '#AA9180')}</svg>`],
    ['Do not remove or recolour the Lumen', `<svg ${box}>${P.map((p) => (p.role === 'lumen' ? '' : `<path d="${p.d}" fill="#602733"/>`)).join('')}</svg>`],
    ['No low contrast', `<svg ${box}><rect x="0" y="40" width="140" height="60" fill="#AA9180"/>${g('#8E837D', '#D6C0B2')}</svg>`],
    ['Do not add words to the wordmark', `<svg ${box}>${g('#602733', '#AA9180', 'transform="translate(-14 0) scale(.85)"')}<text x="98" y="78" font-family="Jost" font-size="9" fill="#602733">GROUP</text></svg>`],
    ['Do not set "SIRAJ" in a font', `<svg ${box}><text x="70" y="80" text-anchor="middle" font-family="Jost" font-size="26" font-weight="600" fill="#602733" letter-spacing="2">SIRAJ</text></svg>`],
  ];
  return `<div class="mis">${ex.map(([t, s]) => `<figure><div class="mx">${s}<span class="x">✕</span></div><figcaption>${t}</figcaption></figure>`).join('')}</div>`;
}

// ---- bezier curve diagrams ----------------------------------------------------------------------------
function curves() {
  const E = TOK.motion.easing;
  return `<div class="curves">${Object.entries(E).map(([k, v]) => { const [a, b, c, d] = v.points; return `<figure><svg viewBox="-8 -8 116 116"><rect x="0" y="0" width="100" height="100" fill="none" stroke="#E3D6CC"/><path d="M0,100 C${a * 100},${100 - b * 100} ${c * 100},${100 - d * 100} 100,0" fill="none" stroke="#602733" stroke-width="2.2"/><line x1="0" y1="100" x2="${a * 100}" y2="${100 - b * 100}" stroke="#AA9180" stroke-width=".8"/><line x1="100" y1="0" x2="${c * 100}" y2="${100 - d * 100}" stroke="#AA9180" stroke-width=".8"/><rect x="${a * 100 - 2}" y="${100 - b * 100 - 2}" width="4" height="4" fill="#AA9180" transform="rotate(45 ${a * 100} ${100 - b * 100})"/><rect x="${c * 100 - 2}" y="${100 - d * 100 - 2}" width="4" height="4" fill="#AA9180" transform="rotate(45 ${c * 100} ${100 - d * 100})"/></svg><figcaption><b>${k}</b><span>(${v.points.join(', ')})</span></figcaption></figure>`; }).join('')}</div>`;
}

// ---- simple brand charts (data-viz page) --------------------------------------------------------------
function charts() {
  const bars = [610, 655, 702, 748, 812, 871];
  const bar = `<svg viewBox="0 0 520 300"><g>${[0, 1, 2, 3].map((i) => `<line x1="40" x2="510" y1="${40 + i * 60}" y2="${40 + i * 60}" stroke="#E3D6CC"/>`).join('')}${bars.map((v, i) => `<rect x="${60 + i * 75}" y="${220 - (v - 500) * 0.45}" width="44" height="${(v - 500) * 0.45}" fill="${i === 5 ? '#602733' : '#D6C0B2'}"/><text x="${82 + i * 75}" y="${212 - (v - 500) * 0.45}" font-size="13" text-anchor="middle" fill="#3B3436">${v}</text><text x="${82 + i * 75}" y="242" font-size="11" letter-spacing="1.5" text-anchor="middle" fill="#8E837D">${2021 + i}</text>`).join('')}<line x1="40" x2="510" y1="220" y2="220" stroke="#3B3436"/></g></svg>`;
  const pts = [[0, 40], [1, 52], [2, 61], [3, 75], [4, 88], [5, 100], [6, 118], [7, 131]];
  const line = `<svg viewBox="0 0 520 300">${[0, 1, 2, 3].map((i) => `<line x1="40" x2="510" y1="${40 + i * 60}" y2="${40 + i * 60}" stroke="#E3D6CC"/>`).join('')}<path d="M${pts.map(([x, y]) => `${60 + x * 62},${220 - y * 1.3}`).join(' L')}" fill="none" stroke="#602733" stroke-width="2.5"/><path d="M${pts.map(([x, y]) => `${60 + x * 62},${220 - y * 0.9}`).join(' L')}" fill="none" stroke="#AA9180" stroke-width="1.5" stroke-dasharray="5 5"/><rect x="${60 + 7 * 62 - 6}" y="${220 - 131 * 1.3 - 6}" width="12" height="12" fill="#602733" transform="rotate(45 ${60 + 7 * 62} ${220 - 131 * 1.3})"/><text x="${60 + 7 * 62 - 14}" y="${220 - 131 * 1.3 + 4}" text-anchor="end" font-size="13" fill="#602733">168 sold</text><text x="${60 + 7 * 62 - 14}" y="${220 - 131 * 0.9 + 18}" text-anchor="end" font-size="12" fill="#8E837D">Plan</text><line x1="40" x2="510" y1="220" y2="220" stroke="#3B3436"/></svg>`;
  const mix = [['1 BR', 40, '#D6C0B2'], ['2 BR', 72, '#AA9180'], ['3 BR', 44, '#602733'], ['Penthouse', 12, '#2C0F12']];
  let x = 40; const tot = 168;
  const stack = `<svg viewBox="0 0 520 300">${mix.map(([n, v, c]) => { const w = v / tot * 470; const s = `<rect x="${x}" y="110" width="${w - 2}" height="60" fill="${c}"/><text x="${x}" y="96" font-size="13" fill="#3B3436">${n}</text><text x="${x}" y="198" font-size="22" font-weight="200" fill="#602733">${v}</text>`; x += w; return s; }).join('')}</svg>`;
  return `<div class="charts"><figure>${bar}<figcaption>Bar: average price per m², OMR. Highlight one bar in Maroon and keep the rest in Sand.</figcaption></figure><figure>${line}<figcaption>Line: sales against plan. Maroon for actuals, Stone dashes for plan, a Lumen marker on the key point, direct labels.</figcaption></figure><figure>${stack}<figcaption>Stacked bar instead of a pie: the unit mix, with values set in light numerals.</figcaption></figure></div>`;
}

// ------------------------------------------------------------------------------------------- content
const P = [];
const photo = (n) => `08-Photography/Library/SIRAJ_Photo_${n}_v1.0.jpg`;
const still = (f, fmt = '16x9') => `06-SIRAJ-Silk/Stills/${f}/SIRAJ_Silk_${f}_${fmt}_web_v1.0.webp`;

// 01 Cover
P.push(page({ dark: true, raw: true, footer: false, cls: 'cover', body: `<div class="dv-bg" style="${bgImg(still('Drape-Lumen'))}"></div><div class="cv-shade"></div>
  <div class="cv">${logo('sand', 120)}<div class="cv-t">Brand Guidelines</div><div class="cv-ar">الدليل الإرشادي للهوية</div><div class="cv-v">Version 1.0 · Official · October 2026</div></div>
  <div class="cv-foot"><span>SIRAJ Real Estate Development</span><span>سراج للتطوير العقاري</span></div>` }));
// 02 Contents (filled later)
P.push('__TOC__');
pageNo++;
// 03 Introduction
P.push(page({ toc: '01 · Introduction', sec: '01 · Introduction', title: 'One brand universe', body: `<div class="cols2"><div><p class="lead">This document defines <b>SIRAJ Brand Identity v1.0</b>: the official visual identity, design system and motion system of SIRAJ Real Estate Development. It is written for designers, developers, marketing teams, video teams and external agencies.</p><p>Everything shown here exists as a production file in the brand repository. Where this document shows an example, the repository contains the editable source and the exports.</p>${rule}<p class="small"><b>How to use it.</b> Read the foundations first: idea, logo, colour, typography and silk. Then use the application chapters as references. When in doubt, choose restraint.</p><p class="small"><b>Source of truth.</b> github.com/Mr-Ghassan/SIRAJ. Tokens, fonts, logos and templates are versioned there.</p></div><div class="stack">${img(photo('Campaign-Silk-Reveal'), 'width:100%;height:520px;object-fit:cover', 'silk-corner-img')}<div class="cap">Silk Reveal: the signature campaign gesture (concept visual).</div></div></div>` }));
// 04 Strategy · positioning
P.push(page({ toc: '02 · Strategic positioning', sec: '02 · Strategy', title: 'SIRAJ does not begin with scale. It begins with a standard.', body: `<div class="cols2"><div><div class="eb">Positioning</div><p class="lead" style="font-size:40px;line-height:1.3;color:#602733">SIRAJ develops considered real estate projects designed to create lasting value.</p><p class="ar-lead">سراج تطور مشاريع عقارية مدروسة تصنع قيمة تستمر.</p>${rule}<p>A company that knows exactly <b>what</b> it develops, <b>why</b>, and <b>for whom</b>. It chooses the right opportunity, develops it with care, presents it with a strong identity, and turns it into an asset of lasting value.</p></div>
  <div><h4>Every SIRAJ project has</h4><div class="pillist">${['A considered location', 'A clear concept', 'Coherent design', 'Investment feasibility', 'Quality of execution', 'Strong marketability', 'Long-term value for buyer and investor'].map((t) => `<div><i></i>${t}</div>`).join('')}</div><div class="principle"><div>Start with one strong project. Build a trusted name. Expand with purpose.</div><div class="ar">نبدأ بمشروع قوي، نبني اسمًا موثوقًا، ثم نتوسع بغاية واضحة.</div></div></div></div>` }));
P.push(page({ toc: '03 · PROVE → EXPAND → SCALE', sec: '03 · Growth', title: 'PROVE → EXPAND → SCALE', body: `<div class="growth"><svg viewBox="0 0 640 640" class="circles">${[300, 240, 180, 120, 60].map((r, i) => `<circle cx="320" cy="320" r="${r}" fill="none" stroke="${i === 4 ? '#602733' : '#AA9180'}" stroke-width="${i === 4 ? 2 : 1}" opacity="${0.35 + i * 0.15}"/>`).join('')}<rect x="306" y="306" width="28" height="28" fill="#602733" transform="rotate(45 320 320)"/>${[['The Founding Project', 60], ['Projects across Muscat', 120], ['Product diversification · partnerships', 180], ['Expansion within Oman', 240], ['Assets for others · selected regional', 300]].map(([t, r]) => `<text x="320" y="${320 - r + 22}" text-anchor="middle" font-size="13" letter-spacing="1" fill="#3B3436" font-family="Jost">${t}</text>`).join('')}</svg>
  <div class="phases">${[['PROVE', 'إثبات', 'One strong, distinctive project in Muscat that proves product quality, brand strength, management, marketing, sales velocity, delivery and customer satisfaction.'], ['EXPAND', 'توسّع', 'Selective new projects across Muscat: residential compounds, apartments, mixed-use, commercial, investment and serviced compounds.'], ['SCALE', 'نمو', 'Other governorates, larger projects, landowner and investor partnerships, development for others, and selected regional markets.']].map(([a, ar, t]) => `<div><b>${a}</b><span class="ar">${ar}</span><p>${t}</p></div>`).join('')}<p class="small mut">Expansion is never a goal in itself. The test is whether SIRAJ can deliver a project that carries its standard and value in that market.</p></div></div>` }));
P.push(page({ toc: '04 · The Founding Project', sec: '04 · The Founding Project', title: 'The project that establishes the SIRAJ standard', body: `<div class="cols2"><div><p class="lead">The first project in Muscat is not just the first project. It is the company's introduction to the market and its quality reference for everything that follows.</p><div class="pillist">${['Proof of capability', 'The introduction to the market', 'The quality reference for future projects', 'A long-term marketing asset', 'The foundation of trust for investors, clients, partners, banks and brokers'].map((t) => `<div><i></i>${t}</div>`).join('')}</div><p class="small mut">In corporate communication, the first project carries the honour line «The Founding Project · المشروع المؤسس».</p></div><div>${img(exists('08-Photography/Founding-Project') && first('08-Photography/Founding-Project', /Official|Front/) || photo('Residential-Tower-Golden-Hour'), 'width:100%;height:680px;object-fit:cover', 'silk-corner-img')}</div></div>` }));
// 05 Brand idea
P.push(page({ toc: '05 · Brand idea', sec: '05 · Brand idea', title: 'The lamp sets the standard. Silk carries it. Architecture makes it last.', body: `<div class="cols3 idea">
  <div><div class="big-lumen"></div><h3>Light · the Lumen ◆</h3><p>Siraj (سِراج) means <i>the lamp</i>: one steady light against which everything is seen. The two stone diamonds above the I and the J are its flames, and they mark the standard.</p></div>
  <div>${img('05-Graphic-System/PNG/SIRAJ_Silk-Blade_Maroon_v1.0.png', 'height:120px;margin-bottom:28px')}<h3>Silk · the philosophy</h3><p>Soft yet strong, flexible yet cohesive, simple in material and rich in presence, changing with light. Flexibility in thinking, precision in execution, fluidity in experience.</p></div>
  <div><div class="arch-ic"></div><h3>Architecture · lasting value</h3><p>The grid, square corners, real buildings and generous space express permanence and value. Architecture always comes first.</p></div></div>
  <div class="manifesto">SIRAJ — Architecture shaped with the elegance, continuity and controlled movement of silk.</div>` }));
// 06 Personality & voice
P.push(page({ toc: '06 · Personality & voice', sec: '06 · Personality & voice', title: 'Confident without noise, luxurious without exaggeration', body: `<div class="cols2"><div><div class="pers">${[['Confident', 'without noise'], ['Luxurious', 'without exaggeration'], ['Modern', 'without losing dignity'], ['Investment-minded', 'without being dry'], ['Creative', 'without becoming experimental'], ['Ambitious', 'without pretension']].map(([a, b]) => `<div><b>${a}</b><span>${b}</span></div>`).join('')}</div><p class="small" style="margin-top:24px">The language is <b>clear, calm, intelligent, confident and persuasive.</b></p></div>
  <div><table class="t"><tr><th>We rely on</th><th>We never use</th></tr>${[['Facts and numbers', 'Exaggeration'], ['Design and product quality', '“The most luxurious ever” · «الأفخم على الإطلاق»'], ['Location', '“Once-in-a-lifetime opportunity” · «الفرصة التي لن تتكرر»'], ['Vision and value', 'Excessive sales language'], ['Labelled, verifiable figures', 'Unsupported investment promises']].map(([a, b]) => `<tr><td>${a}</td><td class="mut">${b}</td></tr>`).join('')}</table>
  <div class="heads">${[['A residence shaped by light and silence.', 'مساكن تتشكّل بالضوء والسكينة.'], ['The project that sets the SIRAJ standard.', 'المشروع الذي يؤسس معيار سراج.'], ['Value that lasts.', 'قيمة تستمر.']].map(([e, a]) => `<div class="hd"><div class="en">${e}</div><div class="ar">${a}</div></div>`).join('')}</div></div></div>` }));
// Marketing framework
P.push(page({ toc: '07 · Value-based marketing', sec: '07 · Marketing framework', title: 'From selling the unit to selling the value', body: `<p class="lead" style="max-width:1300px">Every project has a story, an idea, a personality, a clear value, and a convincing reason to buy and to invest. A client must understand within seconds <b>why this project is different.</b></p><div class="pillars">${[['location', 'Location', 'الموقع', 'Why here, and why will its value grow?'], ['floor-plan', 'Product', 'المنتج', 'How is it designed for the client and the market?'], ['view', 'Experience', 'التجربة', 'How will it feel to live or invest here?'], ['investment', 'Investment value', 'القيمة الاستثمارية', 'Why is it an asset, not just a unit?'], ['security', 'Trust', 'الثقة', 'Who develops it, and how will it be delivered and managed?']].map(([ic, a, ar, q], i) => `<div><span class="n">0${i + 1}</span>${img(`07-Icon-System/svg/outline/siraj-icon-${ic}.svg`, 'width:56px;height:56px')}<b>${a}</b><span class="ar">${ar}</span><p>${q}</p></div>`).join('')}</div><p class="small mut" style="margin-top:28px">Marketing is part of development, not a department that comes after it. It begins with land selection, market study, the client, unit mix, pricing, amenities, name, identity and the customer journey. <b>We build what the market needs and can absorb.</b></p>` }));
P.push(page({ toc: '08 · Campaign lifecycle', sec: '08 · Campaign lifecycle', title: 'PRE-LAUNCH · LAUNCH · SUSTAIN', body: `<div class="life">${[['PRE-LAUNCH', 'Build interest without revealing everything', 'Veil: silk wraps or partially conceals the building', 'Teasers, register-interest page, broker kit, PR, project-story film', photo('Campaign-Silk-Wrap')], ['LAUNCH', 'Maximum market focus in a short time', 'Reveal: silk sweeps away (Silk Reveal, Silk Sweep)', 'Launch film, event, outdoor, digital, brochure, price list', photo('Campaign-Silk-Reveal')], ['SUSTAIN', 'Momentum until sell-out and handover', 'Connect: one ribbon links the progress stories', 'Construction updates, testimonials, investment content, remaining units, handover', photo('Construction-Site-Dawn')]].map(([a, b, c, d, im]) => `<div>${img(im, 'width:100%;height:330px;object-fit:cover')}<b>${a}</b><p>${b}</p><p class="small"><span class="lum-i"></span>${c}</p><p class="small mut">${d}</p></div>`).join('')}</div>` }));
P.push(page({ toc: '09 · Brand architecture', sec: '09 · Brand architecture', title: 'Every project a brand, clearly linked to SIRAJ', body: `<div class="cols2"><div><p class="lead">Each project is treated as a brand of its own within the SIRAJ system, with its own name, story, personality and imagery, and it always carries the SIRAJ endorsement.</p><table class="t small"><tr><th>Shared by every project</th><th>Owned by each project</th></tr><tr><td>Typography, grid, Lumen, silk reveal, SIRAJ Silk Grade, voice, endorsement</td><td>Name, story, project typographic mark, photography, architecture, optional accent from the palette</td></tr></table><p class="small" style="margin-top:20px"><b>SIRAJ projects should not all look alike, but they should all feel like SIRAJ.</b> Future service lines (development management, advisory, asset management) use descriptor lockups under the official wordmark, and are introduced only when the capability exists.</p></div><div class="arch-tree"><div class="mb">${logo('primary', 64)}</div><div class="line"></div><div class="projs">${[['Noor Residences', 'مساكن نور'], ['Harir Villas', 'فلل حرير'], ['Qandeel Square', 'ساحة قنديل']].map(([e, a]) => `<div><b>${e}</b><span class="ar">${a}</span><em>A SIRAJ development · من تطوير سراج</em></div>`).join('')}</div>${img(first('14-Property-Marketing/00-Endorsement-Lockup', /\.(svg|png)$/), 'height:110px;margin:40px auto 0')}<p class="small mut" style="text-align:center">Project names shown are demonstration names.</p></div></div>` }));
// 07 SIRAJ Silk concept
P.push(page({ toc: 'The SIRAJ Silk concept', sec: 'SIRAJ Silk', title: 'Silk is a philosophy and a behaviour', body: `<div class="cols2"><div><p class="lead">Soft yet strong. Flexible yet cohesive. Simple in material, rich in presence, changing with light and movement. Silk is SIRAJ's character: <b>flexibility in thinking, precision in execution, fluidity in experience.</b></p><div class="beh">${[['Reveal', 'Silk moves away to uncover architecture or content.'], ['Frame', 'Two silk forms or a Silk Corner frame the subject.'], ['Connect', 'A single ribbon or line links pages, scenes and campaigns.'], ['Guide', 'Silk travels along the 51° axis and leads the eye.'], ['Transition', 'Silk carries one scene into the next.']].map(([a, b]) => `<div><b>${a}</b><span>${b}</span></div>`).join('')}</div><p class="small mut">Hierarchy on every layout: architecture first, information second, silk as the signature gesture, logo as the final identifier.</p></div><div>${img(still('Ribbon-Pair'), 'width:100%;height:600px;object-fit:cover')}</div></div>` }));

// LOGO
P.push(divider('06', 'Logo', 'الشعار', still('Drape-Deep'), '06 · Logo'));
P.push(page({ sec: '06 · Logo', title: 'The official wordmark', body: `<div class="logo-hero">${logo('primary', 230)}</div><div class="cols3 small"><div><b>Fixed geometry.</b> The wordmark is reproduced exactly from the supplied Illustrator master. It is never redrawn.</div><div><b>Stencil capitals.</b> The calligraphic S and the tapering blades of R and A are the origin of the Silk Blade.</div><div><b>Lumen ◆.</b> The stone diamonds on the I and J are the light of the lamp, and they are part of the logo.</div></div>` }));
P.push(page({ toc: '07 · Logo construction', sec: '07 · Construction', title: 'Construction and proportion', body: `${img('01-Logos/Construction/SIRAJ_Logo_Construction_v1.0.png', 'width:100%;max-height:640px;object-fit:contain')}<div class="cols3 small"><div><b>W : H = 3.49 : 1.</b> Grid unit X is the I-stem width (H ÷ 5.7).</div><div><b>Lumen</b> is 0.20 H high, set at 45° and centred on the stem.</div><div><b>Baseline</b> is shared by all letters; the A apex sets the cap line.</div></div>` }));
P.push(page({ toc: '08 · Clear space & minimum size', sec: '08 · Clear space', title: 'Clear space and minimum size', body: `<div class="cols2"><div class="cs-demo">${img('01-Logos/SVG/SIRAJ_Logo_Primary_v1.0_ClearSpace.svg', 'width:100%;outline:2px dashed #AA9180;outline-offset:-2px;background:#fff')}</div><div><p class="lead">Keep a clear space of <b>½ H</b> on every side, where H is the height of the wordmark.</p><table class="t"><tr><th>Medium</th><th>Minimum width</th></tr><tr><td>Screen</td><td>96 px</td></tr><tr><td>Print</td><td>25 mm</td></tr><tr><td>Embroidery / emboss</td><td>40 mm</td></tr><tr><td>Signage (viewing ≤ 10 m)</td><td>600 mm</td></tr></table><p class="small">Below the minimum size, use the S monogram (avatars and favicons only).</p><div class="mins">${[200, 140, 96].map((w) => `<div>${logo('primary', w / L.RATIO)}<span>${w}px</span></div>`).join('')}</div></div></div>` }));
P.push(page({ toc: '09 · Logo variants', sec: '09 · Variants', title: 'Colour variants and approved backgrounds', body: `<div class="vgrid">${[['primary', '#F7F2ED', 'Primary · Ivory'], ['primary', '#FFFFFF', 'Primary · White'], ['deep', '#D6C0B2', 'Deep · Sand'], ['sand', '#602733', 'Sand · Maroon'], ['sand', '#2C0F12', 'Sand · Deep'], ['sand', 'linear-gradient(51deg,#2C0F12,#602733)', 'Sand · Gradient G1'], ['white', `url('${rel(photo('Villa-Community-Dusk'))}') center/cover`, 'White · Photography'], ['mono-black', '#FFFFFF', 'Mono Black'], ['mono-white', '#170608', 'Mono White']].map(([v, bg, n]) => `<figure><div class="vt" style="background:${bg}">${logo(v, 54)}</div><figcaption>${n}</figcaption></figure>`).join('')}</div>` }));
P.push(page({ toc: '10 · Bilingual lockups', sec: '10 · Lockups', title: 'Bilingual lockups', body: `<div class="lk">${img('01-Logos/Lockups/SIRAJ_Lockup_Horizontal_Primary_v1.0.svg', 'height:150px')}<div class="lk2">${img('01-Logos/Lockups/SIRAJ_Lockup_Stacked_Primary_v1.0.svg', 'height:330px')}<div class="lkd">${img('01-Logos/Lockups/SIRAJ_Lockup_Arabic_Reversed_v1.0.svg', 'height:300px')}</div>${img('01-Logos/Lockups/SIRAJ_Lockup_Descriptor_Primary_v1.0.svg', 'height:200px')}</div></div><p class="small">These are typographic lockups: the Arabic name is set in Tajawal and the descriptor in Jost, both outlined. Use the horizontal lockup for letterheads and headers, the stacked lockup for covers and hoardings, and the Arabic-led lockup for Arabic-first communication. A bespoke Arabic wordmark is recommended as a future extension.</p>` }));
P.push(page({ sec: '10 · Lockups', title: 'Monogram, favicon and avatars', body: `<div class="mono">${img('01-Logos/PNG/SIRAJ_Monogram-S_Sand-on-G1_1024px.png', 'width:300px')}${img('01-Logos/PNG/SIRAJ_Monogram-S_Maroon-on-Ivory_1024px.png', 'width:300px')}${img('01-Logos/Dark/SIRAJ_Social-Avatar_Circle_v1.0.png', 'width:300px')}<div class="favs">${[16, 32, 48].map((s) => img(`01-Logos/PNG/Favicon/SIRAJ_Favicon_${s}px.png`, `width:${s * 2}px;image-rendering:pixelated`)).join('')}</div></div><p class="small">The S is lifted unchanged from the wordmark. It is for app icons, favicons and avatars only; it never replaces the wordmark in communication.</p>` }));
P.push(page({ toc: '11 · Incorrect usage', sec: '11 · Incorrect usage', title: 'Incorrect usage', body: misuse() }));

// COLOUR
P.push(divider('12', 'Colour', 'الألوان', still('Ribbon-Sweep'), '12 · Colour'));
P.push(page({ sec: '12 · Colour', title: 'Official palette', body: `<div class="swgrid4">${PAL.filter((e) => e.tier === 'Official').map((e) => swatch(e, true)).join('')}</div><div class="swgrid5">${PAL.filter((e) => ['SIRAJ Shadow', 'Silk Highlight', 'Silk Midtone', 'Silk Dark'].includes(e.name)).map((e) => swatch(e)).join('')}</div><p class="small mut">The four official colours come directly from the master artboards. <b>Status: approved</b> (HEX, RGB, CMYK, Pantone), 11 October 2026.</p>` }));
P.push(page({ sec: '12 · Colour', title: 'Neutrals and proportion', body: `<div class="swgrid5">${PAL.filter((e) => e.tier === 'Neutral').map((e) => swatch(e)).join('')}</div><div class="prop"><div><h4>Light environment</h4><div class="bar">${[['#F7F2ED', 60], ['#602733', 18], ['#3B3436', 12], ['#D6C0B2', 7], ['#AA9180', 3]].map(([c, w]) => `<span style="background:${c};flex:${w}">${w}%</span>`).join('')}</div></div><div><h4>Dark environment</h4><div class="bar">${[['#170608', 55], ['#602733', 25], ['#D6C0B2', 12], ['#F7F2ED', 5], ['#AA9180', 3]].map(([c, w]) => `<span style="background:${c};flex:${w}">${w}%</span>`).join('')}</div></div></div>` }));
P.push(page({ toc: '13 · Accessibility', sec: '13 · Accessibility', title: 'Contrast and accessibility', body: `<div class="acc">${[['#3B3436', '#F7F2ED', 'Graphite on Ivory', '10.9', 'AAA'], ['#602733', '#F7F2ED', 'Maroon on Ivory', '10.3', 'AAA'], ['#6B625E', '#F7F2ED', 'Ash on Ivory', '5.3', 'AA'], ['#AA9180', '#F7F2ED', 'Stone on Ivory', '2.7', 'Decorative only'], ['#D6C0B2', '#2C0F12', 'Sand on Deep', '10.2', 'AAA'], ['#D6C0B2', '#602733', 'Sand on Maroon', '6.6', 'AA'], ['#F7F2ED', '#602733', 'Ivory on Maroon', '10.3', 'AAA'], ['#AA9180', '#2C0F12', 'Stone on Deep', '6.0', 'AA']].map(([f, b, n, r, s]) => `<div class="ac" style="background:${b};color:${f}"><div class="aa">Aa ◆</div><div><b>${n}</b><span>${r} : 1 · ${s}</span></div></div>`).join('')}</div><p class="small">Body text must meet at least 4.5 : 1 and large text 3 : 1. Never set text in Stone on light backgrounds. Use focus rings of 2 px in Maroon (light) or Sand (dark) with a 3 px offset.</p>` }));
P.push(page({ toc: '14 · Gradients', sec: '14 · Gradients', title: 'Light travelling across silk', body: `<div class="grads">${Object.entries(TOK.gradient).map(([k, v]) => `<figure><div style="background:${v}"></div><figcaption><b>${k}</b><span>${v.replace(/linear-gradient|radial-gradient/, '').slice(0, 92)}</span></figcaption></figure>`).join('')}</div>${doList(['The light source is always at the upper end (51° Silk Axis).', 'Use at most 3 hues, all from the maroon family.', 'Move gradients only as light travelling: a 10–15% stop shift over 2 s or more.'])}${doList(['No rainbow or SaaS gradients, gold or metallics, gradients in the logo, or gradients behind small text.'], false)}` }));
P.push(page({ toc: '15 · Light & dark environments', sec: '15 · Environments', title: 'Light and dark brand environments', body: `<div class="envs"><div class="env l"><div class="eb">Light environment</div><h3>Ivory, Graphite, Maroon</h3><p>Corporate communication, documents, websites, sales material. Silk is used as an accent.</p>${logo('primary', 44)}</div><div class="env d" style="${bgImg(still('Drape-Deep'))}"><div class="eb" style="color:#D6C0B2">Dark environment</div><h3>Shadow, Deep, Sand</h3><p>Film, events, hero moments, evening campaigns. Silk carries the light.</p>${logo('sand', 44)}</div></div>` }));

// TYPOGRAPHY
