// SILK
P.push(divider('20', 'SIRAJ Silk', 'حرير سراج', still('Drape-Lumen'), '20 · SIRAJ Silk'));
P.push(page({ sec: '20 · SIRAJ Silk', title: 'Official silk formations', body: `<div class="forms">${['Drape-Lumen', 'Drape-Deep', 'Drape-Fall', 'Ribbon-Sweep', 'Ribbon-Ivory', 'Ribbon-Pair', 'Horizon-Ivory', 'Horizon-Deep', 'Fold-Corner-Ivory', 'Gateway', 'Wrap'].map((f) => `<figure>${img(still(f), 'width:100%;aspect-ratio:16/9;object-fit:cover')}<figcaption>${f.replace('-', ' · ')}</figcaption></figure>`).join('')}<figure class="note"><b>SIRAJ Silk Engine</b><span>A proprietary WebGL renderer with deterministic, palette-locked output, used for stills, the web and motion. 06-SIRAJ-Silk/engine</span></figure></div>` }));
P.push(page({ toc: '21 · Silk rules', sec: '21 · Silk rules', title: 'How much, where, how', body: `<div class="cols2"><div>${doList(['Use one silk gesture per layout.', 'Keep silk to 35% of any layout that shows architecture or information.', 'Enter from the lower start and leave toward the upper end.', 'Light comes from a single warm source at the upper end.', 'Keep it satin and maroon, either architectural or precious in scale.', 'Show no more than three dominant folds.'])}</div><div>${doList(['Never hide the property.', 'Never let silk touch, cross or frame the logo.', 'Never use silk as a fashion or garment reference, with bodies or mannequins.', 'Never use glossy plastic, metallic, iridescent or non-maroon silk.', 'Never crumple silk into chaotic flutter.', 'Never cover every layout with silk: restraint is the luxury.'], false)}</div></div><div class="cols4">${['Ribbon-Ivory', 'Horizon-Ivory', 'Fold-Corner-Ivory', 'Gateway'].map((f) => img(still(f), 'width:100%;aspect-ratio:16/9;object-fit:cover')).join('')}</div>` }));
P.push(page({ toc: '22 · Silk × Architecture', sec: '22 · Silk × Architecture', title: 'Silk Wrap · Reveal · Foundation · Gateway', body: `<div class="camp">${img(photo('Campaign-Silk-Wrap'), '', 'tall')}${img(photo('Campaign-Silk-Reveal'))}${img(photo('Campaign-Silk-Foundation'))}${img(photo('Campaign-Silk-Gateway'), '', 'tall')}</div><p class="small mut">These are AI-generated concept visuals that show the art direction. Replace them with commissioned CGI or photography of real projects before public use.</p>` }));
// PHOTOGRAPHY
P.push(divider('23', 'Photography', 'التصوير', photo('Residential-Tower-Golden-Hour'), '23 · Photography'));
P.push(page({ sec: '23 · Photography', title: 'Architecture first, warm natural light', body: `<div class="ph-grid">${['Residential-Tower-Golden-Hour', 'Villa-Community-Dusk', 'Apartment-Interior-Sea-View', 'Mixed-Use-Plaza-Evening', 'Commercial-Facade-Morning', 'Construction-Site-Dawn', 'Sales-Centre-Interior', 'Aerial-Coastal-Community'].map((n) => `<figure>${img(photo(n))}<figcaption>${n.replace(/-/g, ' ')}</figcaption></figure>`).join('')}</div>` }));
P.push(page({ toc: '24 · Architectural imagery', sec: '24 · Imagery direction', title: 'Direction by subject', body: `<table class="t small"><tr><th>Subject</th><th>Composition</th><th>Camera</th><th>Light</th><th>People</th></tr>${[['Exteriors', 'Corrected verticals; sky as negative space', '24–35 mm, eye level or slightly low', 'Golden or blue hour', 'None, or tiny for scale'], ['Interiors', 'One- or two-point perspective; view through glazing', '24 mm tilt-shift', 'Raking daylight', 'None, or a hand'], ['Drone', 'Masterplan legible, context of sea and mountains', 'Oblique 45–60°', 'Low sun, soft haze', 'None'], ['Construction', 'Precision and progress', 'Wide, tripod', 'Dawn', 'Workers in PPE, distant'], ['Lifestyle', 'Candid, architecture dominant', '35–50 mm', 'Evening warmth', 'A mix of Omani and international; Omani men in dishdasha and massar; all women in hijab'], ['Investment', 'Details: models, materials, plans', '50–90 mm', 'Soft window light', 'Hands only']].map((r) => `<tr>${r.map((c, i) => `<td>${i ? c : `<b>${c}</b>`}</td>`).join('')}</tr>`).join('')}</table><div class="cols2">${doList(['Strong architecture and premium materials.', 'Warm, controlled contrast with cinematic depth.', 'Authentic Omani context.'])}${doList(['No over-saturated HDR, fake smiles, obvious stock or lens flares.', 'No unrealistic skies, hyper-glossy renders, gold or chandeliers.'], false)}</div><div class="cols2">${doList(['<b>People: mandatory rule.</b> Women appear only in a hijab that fully covers hair and neck, with loose, modest clothing. <span dir="rtl">لا تُستخدم إلا صور نساء محجبات دون إظهار الشعر أو أي عورة.</span>', 'Casting is a natural mix of Omani and international residents, investors and professionals. Omani men wear the dishdasha with the Omani massar (المصر).'])}${doList(['No uncovered hair, tight or revealing clothing, or intimate poses.', 'Omani men are never shown in the kumma or a Gulf ghutra. The rule covers all imagery: CGI scale figures, stock, AI, video and events.'], false)}</div>` }));
P.push(page({ sec: '24 · Imagery direction', title: 'The SIRAJ Silk Grade', body: `<div class="ba"><figure>${img('08-Photography/Library/Ungraded/SIRAJ_Photo_Campaign-Silk-Reveal_Ungraded_v1.0.jpg')}<figcaption>Before: ungraded</figcaption></figure><figure>${img(photo('Campaign-Silk-Reveal'))}<figcaption>After: SIRAJ Silk Grade v1.0</figcaption></figure></div><p class="small">The 33-point LUT (08-Photography/Grade/SIRAJ_Silk-Grade_v1.0.cube) does four things: it pulls reds to SIRAJ wine-maroon, calms skies, reduces global saturation by 6%, and split-tones shadows to SIRAJ Shadow and highlights to Warm Ivory with a lifted black floor.</p>` }));

