P.push(page({ toc: '29 · Design tokens', sec: '29 · Design tokens', title: 'One source of truth, every platform', body: `<div class="cols2"><div><p class="lead">All foundations live in <b>09-Design-System/tokens/siraj.tokens.json</b> (W3C Design Tokens format), with ${Object.keys(require('../09-Design-System/tokens/build/siraj-tokens.flat.json')).length} tokens covering colour, theme, gradient, type, space, radius, border, shadow, opacity, breakpoint, z-index, motion and component states.</p><table class="t small"><tr><th>Output</th><th>File</th></tr>${[['CSS variables', 'siraj-tokens.css'], ['SCSS', '_siraj-tokens.scss'], ['JS / TS', 'siraj-tokens.mjs · .cjs · .d.ts'], ['Tailwind preset', 'tailwind.preset.cjs'], ['iOS · SwiftUI', 'SirajTokens.swift'], ['Android · Compose', 'SirajTokens.kt'], ['Flat JSON', 'siraj-tokens.flat.json']].map(([a, b]) => `<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</table></div><pre class="code">${fs.readFileSync(path.join(ROOT, '09-Design-System/tokens/build/siraj-tokens.css'), 'utf8').split('\n').slice(1, 34).join('\n').replace(/</g, '&lt;')}</pre></div>` }));

